      "outlook": "高値4,400円を付けた後に始値まで戻された上ヒゲ＋寄り引け同値は買い疲れのサイン。発行済株式数超の出来高も短期筋の集中を示す。株探の相場展望は短期間で2倍超になった銘柄群への警戒を促しており、翌日は当日安値3,955円がサポートとして機能するかが焦点。割れれば調整局面入りとなる。"
