      detail:"14日の適時開示・個別材料記事はなく、10月9日15時発表の上方修正を起点とした継続的な資金流入で値上がり率9位に入った。27年5月期計画を売上118.80億円→138.05億円（+20.7%）、営業益13.55億円→20.00億円（+69.6%）、経常益14.40億円→21.30億円（+48%の上方修正、4期ぶり最高益）、最終益9.75億円→14.80億円、配当42円→50円へ引き上げ、生成AI・AIデータセンター投資に伴う光電融合向けミラー・球面レンズ需要やアライメント用自動ステージ需要が牽引するとした。14日は安値3,250円から終日右肩上がりで15時24分の高値3,920円近辺で引け、585円高の3,905円（売買代金16.9億円）。株探夕刊もレーザー関連の強い上昇トレンド銘柄として取り上げた。",
      outlook:"1Q（6-8月）は売上33.82億円（+35.0%）・営業益5.18億円（3.4倍）で上期進捗49.9%と修正後計画の確度は高い一方、株価は上方修正から3営業日で約26%上昇し短期の過熱感が強い。TSMC決算や10月15日のオキサイド決算など半導体・光電融合関連の業績発表が関連株全体の需給に与える影響に注意したい。"
