      detail:"10月13日18時、米FDAからWarning Letter（警告書、米国時間10月7日付）を受領したと開示した。FDAが2025年下期に日米欧の施設を査察した結果に基づくもので、対象はオリンパスメディカルシステムズ（八王子・日の出）、青森オリンパス、白河オリンパス、独Olympus Winter & IBE、米Gyrus ACMIの計6拠点。指摘は品質マネジメントシステムと機器の設計管理手続きなど関連プロセスに関するもので、会社側は受領から15営業日以内に包括的な回答を提出するとし、警告書は製造・販売・流通を制限せず製品回収も求めず新製品の510(k)申請も制限しないと明記した。それでも2025年にも品質管理でFDA警告書を受け約800億円を投じて改善してきた経緯から「再発」と受け止められ、14日は9時24分に1,697円まで下落、終値は273.5円安の1,759円。日経平均を約37円押し下げた。",
      outlook:"論点は15営業日以内のFDAへの回答提出とその後の進捗開示、2025年の輸入警告のような出荷・供給制限や米国売上への実害が生じるか、品質システム改革にかかる追加コストと11月10日の2Q決算での通期計画（営業益1,460億円＝+50.3%）の修正有無。会社は生産・販売制限なしとしており、実害の有無とコスト計上の見極めが鍵となる。"
