      "delta": "▲898.34（+1.39%）",
      "note": "日経平均は898.34円高の65,324.29円と7営業日ぶりに大幅反発した。10月14日に米クラウド事業者コアウィーブの社債利回りが15%に達しAI投資の継続性に疑念が生じた「コアウィーブ・ショック」以降、日経平均は6日続落で計6,258円安、前日15日は3,318円安と歴代3位の下落幅を記録しており、値ごろ感からの押し目買い需要が蓄積していた。前日の米国市場ではNYダウが3日ぶりに556ドル高と反発、米長期金利の低下を背景に生活必需品・ヘルスケアなどディフェンシブが買われナスダックも上昇した。さらにエヌビディアのジェンスン・フアンCEOが「コアウィーブの資本コストは実際には低下している」と発言したと伝わりAI不安が緩和、東京市場ではAI・半導体関連に買い戻しが集中した。韓国KOSPIが一時5%近く上昇したことも投資家心理を改善させ、上海総合は3,716.2842（+8.8082）、香港ハンセンは24,186.83（+124.11）と揃って堅調。日経平均は64,925.29円で寄り付き、前引けは+1,124円の65,550円、後場に65,712.30円（上げ幅は一時1,300円近く）まで買われたが、引けにかけては日米AI関連企業の決算（メタ21日、マイクロソフト・アルファベット28日、ディスコ22日）を見極めたい姿勢から上げ幅を縮めた。安値は64,800.90円。6日間で6,258円下げたのに対し戻りは898円にとどまり、週間では前週末比3,706円安と5週ぶりの下落で26週移動平均線（65,672円）をわずかに下回ったままである。業種別は33業種中32業種が上昇し、下落は電気・ガス業のみ。上昇率上位はその他製品・機械・保険業・輸送用機器・電気機器で、下位は小売業・パルプ紙・海運業・食料品・非鉄金属だった。寄与度の押し上げは東京エレクトロン+134.00円、ソフトバンクグループ+74.43円、イビデン+74.30円、ベイカレント+50.57円、アドバンテスト+40.99円で上位5銘柄だけで約374円分を稼ぎ、押し下げはファーストリテイリング-66.34円、フジクラ-7.48円、良品計画-6.40円、オリンパス-4.18円、京セラ-3.24円と下位5銘柄で約88円、うち約75%をファーストリテイリング1銘柄が占めた。個別ではベイカレントとSHIFTが好決算でストップ高となり、コンサル・IT人材セクターに資金が集中。もう一つの主役は情報セキュリティ関連株で、ソースネクストが15日に第三者の不正アクセスにより会員の個人情報が最大2,251万9,960件（パスワードを含む）流出したおそれがあると発表し、ベネッセに次ぐ国内歴代2位規模の事案として大型漏洩の連続発生が意識され、サイバートラスト+26.28%、サイバーセキュリティクラウド+21.14%、Ｓ＆Ｊ+16.80%、網屋+16.40%などが急騰した。TOPIXは66.66ポイント高の4,066.00（+1.67%）と反発し、日経平均を上回る上昇率。東証プライムの売買代金は概算7兆6,686億円、売買高は23億7,905万株で、値上がり1,292・値下がり228と8割超の銘柄が上昇した（変わらず銘柄数は当日の各市況記事から取得できなかった）。日経225構成銘柄の内訳は値上がり194・値下がり29・変わらず2、東証プライムの騰落レシオ（25日）は104.36。新発10年債利回りは2.930%（+0.010pt）と株高で3営業日ぶりに反落した。為替は小幅な円高で、株式市場への影響は限定的だった。ドル円は時間外の米10年債利回り上昇を受けたドル買いと、中東情勢の不透明感による原油高止まりが日本の貿易収支悪化観測につながったこと、さらに日経平均の反発によるリスク選好で午前10時ごろ158円18銭まで上昇し、前日のNY高値158円25銭に迫った。しかし午後はウォーシュFRB議長がバンコクでのIMF・世界銀行年次総会で金利判断について「予断を持たない」「年内の会合でFRBが何をするか今言うべきではない」と述べ、今週の米CPI・PPIが予想を上回ったにもかかわらず早期の追加利上げを示唆しなかったため10月27〜28日のFOMCでの据え置き観測が強まり、米長期金利の上昇幅縮小とともに157円80銭まで押し戻された。米フィラデルフィア連銀製造業景況指数と小売売上高が前回を下回ったことも金利を押し下げた。当日の東京市場のレンジは157円80銭〜158円18銭で、株式大引け前後の15時台は157円84銭（前営業日のNY終値比16銭の円高、約-0.10%）。片山財務相が「秩序ある為替市場の維持に向け米財務省と連携して取り組んでいる」「高い緊張感を持って金融市場の動向を注視する」と述べ日米協調介入への警戒感も円を支えた。15時30分からの全国信用組合大会では植田日銀総裁の挨拶が内田副総裁の代読で示されたが「経済・物価情勢に応じて利上げを継続する」との従来方針の再確認にとどまり反応は限定的。夕方は欧州勢の参入でドルが買い戻され、日銀公表の午後5時時点は158円00〜02銭（前日比14銭のドル高・円安）、レポート作成時の18時時点も158円00銭前後で横ばい圏にある。ユーロ円は177円15銭〜177円64銭のレンジで、大引け時点は177円16銭（同10銭の円高、約-0.06%）、午後5時時点は177円57〜61銭（同60銭のユーロ高・円安）、18時時点は177円68銭前後と夕方にかけてユーロ高・円安が進んだ。ユーロドルは15時の1.1224ドルから17時に1.1238ドルへ上昇し、当日レンジは1.1208〜1.1249ドル。当日の円の変動幅は大引け時点でドル円0.1%・ユーロ円0.06%と小さく、輸送用機器・電気機器の上昇や半導体株の寄与度上位は為替ではなく米ハイテク株高に伴う買い戻しが主因であり、小売業が上昇率下位に沈みファーストリテイリング・良品計画・高島屋・イオンが押し下げ上位に並んだ点についても、為替と内需・小売株の因果を明示した当日の記事は確認できなかった。FOMC（10月27〜28日）と日銀金融政策決定会合（10月29〜30日）を控え、来週のドル円予想レンジは157円10銭〜158円90銭とされる。ストップ高は21銘柄、ストップ安は5銘柄だった（いずれも気配・一時ストップを含む株探基準）。"
