      "note": "日経平均は841.28円安の64,075.42円と大幅続落した。始値64,755.49円、高値64,822.22円と小高く始まったが、後場に下げ幅を一時1,100円超へ広げ、安値63,807.15円まで売られたあと64,000円台を回復して引けた。前日の米市場でフィラデルフィア半導体株指数（SOX）が9日ぶりに切り返したことは追い風とみられたが買いは続かず、AIインフラ関連の債務懸念（米コアウィーブの社債利回り急騰とCDS取引急増の報道）、米原油先物の104ドル台への上昇、フランスの大規模デモと財政不安を背景とした世界的な長期金利上昇が重なり、AI・半導体関連に売りが集中した。日経平均と連動性の高い韓国KOSPIが3.73%安と急落したことも投資家心理を冷やした。寄与度の押し下げ上位はソフトバンクグループ-235.43円、東京エレクトロン-134.00円、アドバンテスト-125.13円、フジクラ-58.66円、イビデン-45.71円で、上位5銘柄だけで約599円を押し下げた。押し上げはファーストリテイリング+122.17円、テルモ+17.93円、コナミグループ+13.15円、バンダイナムコホールディングス+11.33円、中外製薬+9.71円で、上位5銘柄の合計は約174円にとどまった。上昇は33業種中9業種のみで、非鉄金属・銀行業・ガラス土石製品・保険業が下落上位、その他製品・小売業・医薬品・精密機器が上昇上位と、ディフェンシブへの資金シフトが鮮明だった。TOPIXは58.27ポイント安の4,009.21（-1.43%）、東証グロース250指数は2.7%安。東証プライムの売買代金は概算6兆7,992億円で2日続けて7兆円を割り込み、売買高は21億4,872万株、値上がり335・値下がり1,181・変わらず37と値下がりが全体の約76%を占めた。為替は小幅な円高。ドル円は東京朝方にイエメン情勢を受けた原油高と日本のインフレ懸念で前日高値を上抜く158円60銭を付けたが、米10年債利回りが朝の5.14%台から5.11%台へ低下したことで日米金利差の縮小が意識され、午後は158円09銭まで下落した。20年国債入札の応札倍率が過去最高となったことやアジア半導体株安によるリスク回避の円買い、日米通貨当局による円安けん制への警戒も上値を抑え、夕方には158円03銭まで下げて当日安値を更新した。株式大引け近辺（15時時点）はドル円158円16銭（前営業日NY終値比34銭の円高）、ユーロ円177円58銭（同15銭の円高）、日銀・インターバンクの午後5時時点は1ドル158円07〜09銭で前日比9銭の円高、1ユーロ177円49〜53銭で同53銭の円安だった。ユーロ円は正午の177円92銭を高値、東京午後に177円52銭まで下げ、参考レンジは177円42〜177円92銭。レポート作成時点の夕方18時台はドル円158円04〜158円22銭のレンジで上昇分を失速、ユーロ円は独ZEW景況感指数（10月28.1、予想30.0）の下振れを受けて177円24銭へ軟化し、ユーロドルも1.1212ドルまで下落した。15時過ぎには通信社が「日銀関係筋、10月会合は政策金利据え置きの公算」と報じ、来週の日銀会合・FOMCを前に157円半ば〜159円手前のレンジ取引の地合いが続いている。ただし当日の円の変動は対ドルで9銭（約0.06%）と極めて小幅で、株探・フィスコ・DZH・共同通信いずれの市況記事も業種別の騰落要因として為替を挙げていない。半導体・AI関連の下落はAI債務懸念と原油高・長期金利上昇が主因で、キオクシアホールディングス、アドバンテスト、レーザーテック、ディスコ、太陽誘電、フジクラ、古河電気工業、イビデンが売られた。輸入比率の高い内需・小売側ではファーストリテイリングが逆行高で寄与度トップ、吉野家ホールディングスが目標株価引き上げで大幅高、医薬品のテルモ・中外製薬も上昇したが、各記事はこれを円高による輸入採算改善ではなく「原油高・金利上昇を嫌気した資金のディフェンシブ株へのローテーション」として説明している。メガバンクの下落も金利上昇に伴う債券評価損懸念が理由で、為替要因ではない。ストップ高は9銘柄、ストップ安は5銘柄（いずれも気配・一時ストップを含む株探基準。ショーケースは一時ストップ高と引けストップ安の両方に該当するため、当サイトではストップ安側に掲載した）。"
