          "outlook": "終値278円は年初来高値800円（3月13日）の3分の1強にとどまり、戻り売り圧力は残る。PTSでは18時台に260円と終値を下回って推移した。26年9月期通期決算の発表は11月16日を予定し、下方修正後の着地と27年9月期計画が焦点となる。材料を伴わない上昇のため、短期資金の離散による反落リスクが意識される。"
