          "detail": "東証プライムの値下がり率トップ。前場は13,940円（9時48分）まで上昇していたが、29日14時の上期決算発表後に売りが殺到し安値10,530円まで崩れた。上期（4-9月）は経常88.36億円（前年同期比2.5倍）で会社計画76億円を16.3%上振れ、営業益86.51億円（2.2倍）、売上538.35億円（43.1%増）と内容自体は極めて良好である。急落の主因は通期予想の据え置きで、通期経常126億円を変えなかったため下期経常は逆算で37.64億円（前年同期比44.4%減）、下期営業益38.49億円（同38.3%減）という大幅減益計算になる。四半期ベースでも営業益は4-6月期51.17億円→7-9月期35.34億円（前四半期比30.9%減）と減速しピークアウト懸念が強まった。需給面では信用買い残1,022,700株（10月23日時点、信用倍率132.82倍、売り残7,700株）が発行済株式数の約9.6%に達する極端な買い長で、投げ売りが連鎖した。出来高1,392,700株は前日の約4.3倍である。",
          "outlook": "3月期決算で、次回は第3四半期決算（発表予定日は未開示）。下落は「好決算＋通期据え置き」の失望が主因なので、決算説明資料や会社側コメントで下期計画の保守性が確認されれば自律反発の余地があり、PTSは18時22分時点11,000円（終値比4.1%高）まで戻している。加えて10月29日16時44分に片山晃氏が保有比率を7.73%→10.36%（1,107,100株、報告義務発生日10月22日）へ引き上げる変更報告書を提出しており需給の支えとなる。一方で巨額の信用買い残の整理圧力と、下期減益計算という構図は残る。株価は3月31日の年初来安値7,100円から10月14日高値17,240円まで約2.4倍化した後の調整局面にあり、高値からは38.7%安となった。"
